#include <iostream>
#include <vector>
#include <iomanip>
#include <algorithm>

using namespace std;

/**
 * Problem: 23781 - Making Change
 * 
 * 解題思路：
 * 1. 目標是最小化交易中交換的硬幣總數（支付的硬幣數 + 找零的硬幣數）。
 * 2. 硬幣面額：5, 10, 20, 50, 100, 200 (以分為單位)。
 * 3. 顧客擁有有限數量的硬幣，店主擁有無限數量的硬幣。
 * 4. 演算法步驟：
 *    - 首先，計算店主找零所需的最小硬幣數 (Unbounded Knapsack)。
 *    - 接著，計算顧客支付不同金額所需的最小硬幣數 (Bounded Knapsack)。
 *    - 最後，遍歷所有可能的支付金額 A (A >= 交易金額)，計算：
 *      總硬幣數 = 顧客支付 A 所需硬幣數 + 店主找零 (A - 交易金額) 所需硬幣數。
 *    - 找出最小值。
 * 5. 金額上限：交易金額最高約 $5.00 (500分)，支付金額上限可設為 700 分。
 */

const int MAX_VAL = 705;
const int INF = 1e9;
int coin_vals[] = {5, 10, 20, 50, 100, 200};

int main() {
    vector<int> shop(MAX_VAL, INF);
    shop[0] = 0;
    for (int c : coin_vals) {
        for (int j = c; j < MAX_VAL; j++) {
            if (shop[j - c] != INF) shop[j] = min(shop[j], shop[j - c] + 1);
        }
    }

    int counts[6];
    double amount_val;
    while (cin >> counts[0] >> counts[1] >> counts[2] >> counts[3] >> counts[4] >> counts[5]) {
        if (counts[0] + counts[1] + counts[2] + counts[3] + counts[4] + counts[5] == 0) break;
        cin >> amount_val;
        int target = (int)(amount_val * 100 + 0.5);

        vector<int> user(MAX_VAL, INF);
        user[0] = 0;
        for (int i = 0; i < 6; i++) {
            int c = coin_vals[i];
            int n = counts[i];
            for (int k = 1; n > 0; k <<= 1) {
                int num = min(k, n);
                n -= num;
                int val = num * c;
                for (int j = MAX_VAL - 1; j >= val; j--) {
                    if (user[j - val] != INF) user[j] = min(user[j], user[j - val] + num);
                }
            }
        }

        int min_coins = INF;
        for (int a = target; a < MAX_VAL; a++) {
            if (user[a] != INF && shop[a - target] != INF) {
                min_coins = min(min_coins, user[a] + shop[a - target]);
            }
        }
        cout << setw(3) << min_coins << endl;
    }
    return 0;
}
